// Normalise : minuscules + suppression accents
function norm(s: string): string {
  return s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '')
}

// Recherche intelligente : exact > début > contient
export function searchFoods(query: string, limit = 10): FoodItem[] {
  const q = norm(query.trim())
  if (q.length < 2) return []
  const exact: FoodItem[] = []
  const starts: FoodItem[] = []
  const contains: FoodItem[] = []
  for (const food of FOODS_DB) {
    const n = norm(food.name)
    if (n === q) exact.push(food)
    else if (n.startsWith(q)) starts.push(food)
    else if (n.includes(q)) contains.push(food)
    if (exact.length + starts.length + contains.length >= limit * 3) break
  }
  return [...exact, ...starts, ...contains].slice(0, limit)
}